-- Eco-Pet: real Mekong Delta places. Safe to re-run. Run AFTER general_quests_schema.sql.
--
-- 8 destinations with 3 place quests each (24 in total): Can Tho, Cai Rang Floating Market, Ben Tre, Vinh Long,
-- My Tho, Sa Dec, Chau Doc and Tra Su. Coordinates come from OpenStreetMap and Wikidata. Two are areas rather
-- than a single building, so their radius is larger: the Mang Thit kilns (q18) and the rice-noodle workshops
-- near Cai Rang (q13).
--
-- Province names follow the July 2025 merger: Ben Tre is now part of Vinh Long province, My Tho and Sa Dec are in
-- Dong Thap province, Chau Doc and Tra Su in An Giang, and Cai Rang / Phong Dien in Can Tho city. The destination
-- names stay the well-known town names travelers use.

alter table public.quests drop constraint if exists quests_required_scene_check;
alter table public.quests add constraint quests_required_scene_check check (required_scene in ('floating market', 'traditional market', 'hiking trail', 'nature landmark', 'river or canal', 'orchard or garden', 'temple or historic building', 'local food stall', 'wildlife or birds', 'hand-rowed boat without a motor', 'bicycle', 'family craft workshop', 'fruit orchard', 'local product stall', 'flower garden'));

on conflict (id) do update set
  type = excluded.type, title_en = excluded.title_en, title_vi = excluded.title_vi,
  description_en = excluded.description_en, description_vi = excluded.description_vi,
  destination = excluded.destination, lat = excluded.lat, lng = excluded.lng, radius_m = excluded.radius_m,
  reward_coins = excluded.reward_coins, required_object = excluded.required_object, required_scene = excluded.required_scene,
  sort = excluded.sort, scope = excluded.scope, photo_proof = excluded.photo_proof, active = true;

-- The demo partner shops are made up (no real business is presented as a partner); they are only moved to
-- sensible spots in the towns where they would be.
update public.vendors set lat = 10.0026, lng = 105.7447 where id = 'v1';
update public.vendors set lat = 10.0329, lng = 105.7869 where id = 'v2';
update public.vendors set lat = 10.0322, lng = 105.7871 where id = 'v3';
update public.vendors set lat = 10.3332, lng = 106.3570 where id = 'v4';
update public.vendors set lat = 10.0346, lng = 105.7880 where id = 'v5';
update public.vendors set lat = 10.0340, lng = 105.7882 where id = 'v6';
