insert into public.quests
  (id, type, title_en, title_vi, description_en, description_vi, destination, lat, lng, radius_m, reward_coins, required_object, required_scene, sort, scope, photo_proof)
values
  ('q1', 'floating_market', 'Shop at the floating market', 'Mua sắm ở chợ nổi', 'Buy something from a boat vendor at Cai Rang and take a photo of it with the market around you. Go early: it is busiest from about 5 to 8 am.', 'Mua một món từ ghe hàng ở chợ nổi Cái Răng và chụp ảnh món đó cùng khung cảnh chợ. Hãy đi sớm: chợ đông nhất từ khoảng 5 đến 8 giờ sáng.', 'Cai Rang Floating Market', 10.0024, 105.74439, 400, 32, null, 'floating market', 1, 'place', 'an item bought from a boat vendor (fruit, drink or food) held or on the boat, with the floating market around it, or the vendor boat with its goods'),
  ('q2', 'traditional_market', 'Shop at a stall by Ninh Kieu', 'Mua sắm ở quầy hàng bến Ninh Kiều', 'Buy something from a small stall at the market by Ninh Kieu Wharf and take a photo of the stall or your purchase.', 'Mua một món ở quầy hàng nhỏ tại khu chợ cạnh bến Ninh Kiều và chụp ảnh quầy hoặc món bạn mua.', 'Can Tho', 10.03153, 105.78757, 350, 25, null, 'traditional market', 2, 'place', 'something bought at a market stall in hand or in a bag, or the stall with its seller and goods'),
  ('q3', 'hiking', 'Explore Tra Su on foot', 'Khám phá Trà Sư bằng đôi chân', 'Walk the long bamboo walkway through the cajuput forest and take a photo of the path.', 'Đi bộ trên cây cầu tre dài xuyên rừng tràm và chụp ảnh con đường.', 'Tra Su', 10.5859, 105.05827, 1500, 38, null, 'hiking trail', 3, 'place', 'the bamboo walkway or forest path walked on foot, with no motor vehicle on it'),
  ('q4', 'craft', 'Visit a coconut candy workshop', 'Ghé xưởng kẹo dừa', 'On Con Phung islet, watch coconut candy being made by hand, buy some, and take a photo of the workshop or your candy.', 'Trên cồn Phụng, xem kẹo dừa được làm thủ công, mua một ít và chụp ảnh xưởng hoặc kẹo của bạn.', 'Ben Tre', 10.33363, 106.35728, 800, 30, null, 'family craft workshop', 4, 'place', 'the workshop where the coconut candy is made, or handmade coconut candy that was bought there'),
  ('q9', 'orchard', 'Buy fruit on An Binh island', 'Mua trái cây trên cù lao An Bình', 'An Binh island, across the river from Vinh Long city, is covered in family fruit orchards. Buy fruit straight from a grower and take a photo of the orchard or your fruit.', 'Cù lao An Bình, bên kia sông đối diện thành phố Vĩnh Long, có rất nhiều vườn trái cây của gia đình. Mua trái cây trực tiếp từ nhà vườn và chụp ảnh vườn hoặc trái cây của bạn.', 'Vinh Long', 10.2932, 105.9868, 3000, 30, null, 'fruit orchard', 9, 'place', 'fruit bought from the grower, or the family orchard with its fruit trees or fruit on display'),
  ('q10', 'cycling', 'Cycle along the Hau River', 'Đạp xe dọc sông Hậu', 'See Ninh Kieu Wharf by bicycle instead of a motorbike or car, and take a photo of your bike by the river.', 'Ngắm bến Ninh Kiều bằng xe đạp thay vì xe máy hay ô tô, và chụp ảnh chiếc xe đạp của bạn bên sông.', 'Can Tho', 10.03369, 105.78843, 500, 40, null, 'bicycle', 10, 'place', 'a bicycle (clearly a bicycle, not a motorbike) with the river or riverside in the background'),
  ('q11', 'floating_market', 'Buy from the boats at Phong Dien', 'Mua hàng trên ghe ở chợ nổi Phong Điền', 'Phong Dien is a small, quiet floating market southwest of Can Tho city. Buy something from a boat and take a photo. Its busiest time is very early, roughly 5:30 to 6:30 am.', 'Phong Điền là chợ nổi nhỏ, yên bình phía tây nam trung tâm Cần Thơ. Mua một món trên ghe và chụp ảnh. Chợ đông nhất rất sớm, khoảng 5 giờ 30 đến 6 giờ 30 sáng.', 'Can Tho', 9.99374, 105.66771, 600, 30, null, 'floating market', 11, 'place', 'an item bought from a boat vendor held or on the boat, with the river market around it'),
  ('q12', 'local_food', 'Breakfast on the water', 'Ăn sáng trên sông', 'Eat a noodle breakfast from a small boat or stall at the floating market and take a photo of your bowl.', 'Ăn sáng món nước từ một ghe hoặc quầy nhỏ ở chợ nổi và chụp ảnh tô của bạn.', 'Cai Rang Floating Market', 10.0024, 105.74439, 400, 28, null, 'local food stall', 12, 'place', 'a bowl of food served at a small floating-market boat or stall, with the water or boats visible'),
  ('q13', 'craft', 'Watch rice noodles being made', 'Xem làm hủ tiếu', 'Visit a family rice-noodle (hu tieu) workshop on the road near Cai Rang, buy a pack, and take a photo of the noodle sheets or your purchase.', 'Ghé một lò hủ tiếu gia đình trên đường gần Cái Răng, mua một gói và chụp ảnh những tấm bánh hoặc món bạn mua.', 'Cai Rang Floating Market', 10.008, 105.736, 3000, 30, null, 'family craft workshop', 13, 'place', 'rice noodle sheets being made or drying in the sun, or a pack of noodles bought at the workshop'),
  ('q14', 'cycling', 'Cycle through the coconut lanes', 'Đạp xe qua các con đường dừa', 'Explore the quiet village lanes around Con Phung by bicycle and take a photo of your bike among the coconut palms.', 'Khám phá những con đường làng yên tĩnh quanh cồn Phụng bằng xe đạp và chụp ảnh chiếc xe đạp của bạn giữa hàng dừa.', 'Ben Tre', 10.33363, 106.35728, 2500, 40, null, 'bicycle', 14, 'place', 'a bicycle (clearly a bicycle, not a motorbike) on a village lane or among coconut palms'),
  ('q15', 'local_goods', 'Buy coconut products at Ben Tre market', 'Mua sản phẩm từ dừa ở chợ Bến Tre', 'Ben Tre is known as the land of coconuts. Buy a coconut product (candy, oil, a coconut-wood craft) from a small seller at the market and take a photo.', 'Bến Tre được gọi là xứ dừa. Mua một sản phẩm từ dừa (kẹo, dầu dừa, đồ gỗ dừa) của một người bán nhỏ ở chợ và chụp ảnh.', 'Ben Tre', 10.23499, 106.37597, 400, 25, null, 'local product stall', 15, 'place', 'a coconut product that was bought, or the small stall selling it with its goods on display'),
  ('q16', 'rowing', 'Paddle into the cajuput forest', 'Chèo xuồng vào rừng tràm', 'After the motorboat, switch to a small rowboat through the duckweed deeper into the forest, and take a photo of it. Birds are most active around 7 to 9 am and 4 to 5 pm.', 'Sau chặng ca nô, chuyển sang xuồng chèo nhỏ len qua lớp bèo vào sâu trong rừng, và chụp ảnh chiếc xuồng. Chim hoạt động nhiều nhất khoảng 7 đến 9 giờ sáng và 4 đến 5 giờ chiều.', 'Tra Su', 10.5859, 105.05827, 1500, 36, null, 'hand-rowed boat without a motor', 16, 'place', 'a small boat moved by oars or a paddle (no engine) among the cajuput trees on the water'),
  ('q17', 'local_goods', 'Buy a local specialty at a small stall', 'Mua đặc sản địa phương ở quầy nhỏ', 'Buy a local product from a small stall near the forest entrance and take a photo of the stall or your purchase.', 'Mua một sản phẩm địa phương ở quầy nhỏ gần cổng rừng và chụp ảnh quầy hoặc món bạn mua.', 'Tra Su', 10.5859, 105.05827, 1500, 25, null, 'local product stall', 17, 'place', 'a local product that was bought, or the small stall selling it with its goods on display'),
  ('q18', 'craft', 'Visit the Mang Thit kilns', 'Ghé lò gạch gốm Mang Thít', 'The Mang Thit area is known for its traditional brick and pottery kilns. Visit a family workshop that still fires pottery, buy a small piece, and take a photo.', 'Vùng Mang Thít nổi tiếng với các lò gạch gốm truyền thống. Ghé một cơ sở gia đình còn nung gốm, mua một món nhỏ và chụp ảnh.', 'Vinh Long', 10.12594, 106.09038, 4000, 32, null, 'family craft workshop', 18, 'place', 'a brick or pottery kiln, or handmade pottery bought from a family workshop'),
  ('q19', 'cycling', 'Cycle An Binh island', 'Đạp xe trên cù lao An Bình', 'The narrow lanes of An Binh island have little traffic and are great for cycling. Explore by bicycle and take a photo of your bike on the island.', 'Những con đường nhỏ trên cù lao An Bình ít xe cộ, rất hợp để đạp xe. Khám phá bằng xe đạp và chụp ảnh chiếc xe đạp của bạn trên cù lao.', 'Vinh Long', 10.2932, 105.9868, 3000, 40, null, 'bicycle', 19, 'place', 'a bicycle (clearly a bicycle, not a motorbike) on a lane among orchards or by the water'),
  ('q20', 'rowing', 'Row through the water-coconut canals', 'Đi xuồng qua kênh rạch dừa nước', 'On Thoi Son island, take a small three-plank sampan rowed by a local through the narrow water-coconut canals, and take a photo of your boat.', 'Trên cồn Thới Sơn, đi chiếc xuồng ba lá do người dân địa phương chèo qua những con rạch nhỏ rợp dừa nước, và chụp ảnh chiếc xuồng.', 'My Tho', 10.33241, 106.3207, 1800, 36, null, 'hand-rowed boat without a motor', 20, 'place', 'a small boat moved by oars or a paddle (no engine) in a narrow canal lined with water-coconut palms'),
  ('q21', 'local_goods', 'Buy honey from a Thoi Son family', 'Mua mật ong của một gia đình ở Thới Sơn', 'Families on Thoi Son island keep bees and make coconut candy. Buy honey or candy from them and take a photo.', 'Các gia đình trên cồn Thới Sơn nuôi ong và làm kẹo dừa. Mua mật ong hoặc kẹo của họ và chụp ảnh.', 'My Tho', 10.33241, 106.3207, 1800, 30, null, 'local product stall', 21, 'place', 'honey or coconut candy that was bought, or the family stall or bee farm selling it'),
  ('q22', 'traditional_market', 'Shop at My Tho market', 'Mua sắm ở chợ Mỹ Tho', 'Buy something from a small seller at My Tho market and take a photo of the stall or your purchase.', 'Mua một món của người bán nhỏ ở chợ Mỹ Tho và chụp ảnh quầy hoặc món bạn mua.', 'My Tho', 10.35724, 106.36789, 400, 25, null, 'traditional market', 22, 'place', 'something bought at a market stall in hand or in a bag, or the stall with its seller and goods'),
  ('q23', 'flowers', 'Buy a plant at the flower village', 'Mua cây hoa ở làng hoa', 'The Sa Dec flower village is made of family gardens. Buy a small plant or flowers from a grower and take a photo of the garden or your purchase.', 'Làng hoa Sa Đéc gồm nhiều vườn hoa của các gia đình. Mua một chậu cây nhỏ hoặc hoa từ nhà vườn và chụp ảnh vườn hoặc món bạn mua.', 'Sa Dec', 10.3175, 105.74556, 2000, 32, null, 'flower garden', 23, 'place', 'flowers or a plant bought from the grower, or the family flower garden with its plants on display'),
  ('q24', 'traditional_market', 'Shop at Sa Dec market', 'Mua sắm ở chợ Sa Đéc', 'Buy something from a small seller at Sa Dec market and take a photo of the stall or your purchase.', 'Mua một món của người bán nhỏ ở chợ Sa Đéc và chụp ảnh quầy hoặc món bạn mua.', 'Sa Dec', 10.2912, 105.76773, 400, 25, null, 'traditional market', 24, 'place', 'something bought at a market stall in hand or in a bag, or the stall with its seller and goods'),
  ('q25', 'local_food', 'Eat at a family-run eatery in Sa Dec', 'Ăn ở quán ăn gia đình tại Sa Đéc', 'Try a local dish at a small family-run eatery in Sa Dec and take a photo of your meal.', 'Thử một món địa phương ở quán ăn nhỏ của gia đình tại Sa Đéc và chụp ảnh bữa ăn của bạn.', 'Sa Dec', 10.2912, 105.76773, 800, 25, null, 'local food stall', 25, 'place', 'a served dish or meal on the table of a small family-run eatery'),
  ('q26', 'local_goods', 'Taste mam at Chau Doc market', 'Thưởng thức mắm ở chợ Châu Đốc', 'Chau Doc is famous for mam (fermented fish). Buy some from one of the long-running stalls at Chau Doc market and take a photo.', 'Châu Đốc nổi tiếng với mắm. Mua một ít ở một trong những sạp mắm lâu năm tại chợ Châu Đốc và chụp ảnh.', 'Chau Doc', 10.71108, 105.11888, 400, 28, null, 'local product stall', 26, 'place', 'fermented fish (mam) that was bought, or the market stall selling it with its goods on display'),
  ('q27', 'craft', 'Buy hand-woven Cham fabric', 'Mua vải dệt tay của người Chăm', 'In the Cham villages across the river from Chau Doc, women weave fabric by hand. Buy a woven piece and take a photo of the loom or your fabric.', 'Ở các làng Chăm bên kia sông đối diện Châu Đốc, phụ nữ dệt vải bằng tay. Mua một món vải dệt và chụp ảnh khung dệt hoặc tấm vải của bạn.', 'Chau Doc', 10.71037, 105.12857, 1500, 32, null, 'family craft workshop', 27, 'place', 'a weaving loom or hand-woven Cham fabric that was bought'),
  ('q28', 'hiking', 'Walk up Sam Mountain', 'Đi bộ lên núi Sam', 'Climb Sam Mountain on foot instead of by motorbike and take a photo of the path or the view.', 'Leo núi Sam bằng đôi chân thay vì đi xe máy và chụp ảnh con đường hoặc khung cảnh.', 'Chau Doc', 10.67667, 105.0775, 1500, 38, null, 'hiking trail', 28, 'place', 'a footpath or steps on the mountain walked on foot, or the view from the path, with no motor vehicle')
